void memory_region_set_dirty(MemoryRegion *mr, hwaddr addr, /* <=== memory_region_set_dirty */ 
                             hwaddr size)
{
    assert(mr->ram_block);
    cpu_physical_memory_set_dirty_range(memory_region_get_ram_addr(mr) + addr,
                                        size,
                                        memory_region_get_dirty_log_mask(mr));
}

void *g_malloc_n(size_t nmemb, size_t size) /* <=== g_malloc_n */ 
{
    size_t sz;
    void *ptr;

    __coverity_negative_sink__(nmemb);
    __coverity_negative_sink__(size);
    sz = nmemb * size;
    ptr = __coverity_alloc__(sz);
    __coverity_mark_as_uninitialized_buffer__(ptr);
    __coverity_mark_as_afm_allocated__(ptr, "g_free");
    return ptr;
}

uint8_t memory_region_get_dirty_log_mask(MemoryRegion *mr) /* <=== memory_region_get_dirty_log_mask */ 
{
    uint8_t mask = mr->dirty_log_mask;
    if (global_dirty_log && mr->ram_block) {
        mask |= (1 << DIRTY_MEMORY_MIGRATION);
    }
    return mask;
}

static inline int get_bpp(SM501State *s, int crt) /* <=== get_bpp */ 
{
    int bpp = crt ? s->dc_crt_control : s->dc_panel_control;
    return 1 << (bpp & 3);
}

ram_addr_t memory_region_get_ram_addr(MemoryRegion *mr) /* <=== memory_region_get_ram_addr */ 
{
    return mr->ram_block ? mr->ram_block->offset : RAM_ADDR_INVALID;
}

#define qemu_log_mask(MASK, FMT, ...)                   \ /* <=== include/qemu/log.h:117:122:qemu_log_mask:3 */ 
    do {                                                \
        if (unlikely(qemu_loglevel_mask(MASK))) {       \
            qemu_log(FMT, ## __VA_ARGS__);              \
        }                                               \
    } while (0)

void *g_malloc(size_t size) /* <=== g_malloc */ 
{
    return g_malloc_n(1, size);
}

static inline int get_height(SM501State *s, int crt) /* <=== get_height */ 
{
    int height = crt ? s->dc_crt_v_total : s->dc_panel_v_total;
    return (height & 0x00000FFF) + 1;
}

static inline int get_width(SM501State *s, int crt) /* <=== get_width */ 
{
    int width = crt ? s->dc_crt_h_total : s->dc_panel_h_total;
    return (width & 0x00000FFF) + 1;
}

static inline bool qemu_loglevel_mask(int mask) /* <=== qemu_loglevel_mask */ 
{
    return (qemu_loglevel & mask) != 0;
}

static ram_addr_t get_fb_addr(SM501State *s, int crt) /* <=== get_fb_addr */ 
{
    return (crt ? s->dc_crt_fb_addr : s->dc_panel_fb_addr) & 0x3FFFFF0;
}

